import java.io.*;import java.util.*;import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;
/** Checks all original operation/register/reference semantics, branch/switch edges and catch regions after removing observation-only hooks. */
public class VerifyNetworkObservation {
 static String H="Lparadox/music/nativeui/NativeMusicNetworkDiagnostics;";
 static Map<String,ClassDef> load(String p)throws Exception{Map<String,ClassDef> r=new TreeMap<>();var z=DexFileFactory.loadDexContainer(new File(p),Opcodes.forApi(28));for(String n:z.getDexEntryNames())for(ClassDef c:z.getEntry(n).getDexFile().getClasses())if(r.put(c.getType(),c)!=null)throw new AssertionError("duplicate "+c.getType());return r;}
 static boolean hook(Instruction i){if(!(i instanceof ReferenceInstruction))return false;Reference r=((ReferenceInstruction)i).getReference();return r instanceof MethodReference&&((MethodReference)r).getDefiningClass().equals(H);}
 static List<String> normal(MethodImplementation impl)throws Exception{List<Instruction> ins=new ArrayList<>();for(Instruction i:impl.getInstructions())ins.add(i);Map<Integer,Integer> index=new HashMap<>(),owners=new HashMap<>();int address=0,logical=0;for(int n=0;n<ins.size();n++){Instruction i=ins.get(n);index.put(address,logical);if(i.getOpcode()==Opcode.PACKED_SWITCH||i.getOpcode()==Opcode.SPARSE_SWITCH)owners.put(address+((OffsetInstruction)i).getCodeOffset(),address);boolean pad=i.getOpcode()==Opcode.NOP&&n+1<ins.size()&&ins.get(n+1) instanceof PayloadInstruction;if(!hook(i)&&!pad)logical++;address+=i.getCodeUnits();}index.put(address,logical);List<String> out=new ArrayList<>();address=0;for(int n=0;n<ins.size();n++){Instruction i=ins.get(n);boolean pad=i.getOpcode()==Opcode.NOP&&n+1<ins.size()&&ins.get(n+1) instanceof PayloadInstruction;if(!hook(i)&&!pad){StringBuilder s=new StringBuilder(i.getOpcode().toString());Set<String> names=new TreeSet<>();for(Class<?> it:i.getClass().getInterfaces())for(var m:it.getMethods())if(m.getParameterCount()==0&&!m.getName().equals("getCodeUnits"))names.add(m.getName());for(String name:names){Object v=i.getClass().getMethod(name).invoke(i);if(name.equals("getCodeOffset")){v=index.get(address+((Number)v).intValue());if(v==null)throw new AssertionError("bad branch");}if(name.equals("getSwitchElements")){int origin=owners.get(address);StringBuilder b=new StringBuilder();for(Object item:(List)v){SwitchElement e=(SwitchElement)item;b.append(e.getKey()).append(':').append(index.get(origin+e.getOffset())).append(',');}v=b.toString();}s.append('|').append(name).append('=').append(v);}out.add(s.toString());}address+=i.getCodeUnits();}
 for(TryBlock<? extends ExceptionHandler> t:impl.getTryBlocks()){StringBuilder b=new StringBuilder("TRY "+index.get(t.getStartCodeAddress())+":"+index.get(t.getStartCodeAddress()+t.getCodeUnitCount()));for(ExceptionHandler h:t.getExceptionHandlers())b.append('|').append(h.getExceptionType()).append(':').append(index.get(h.getHandlerCodeAddress()));out.add(b.toString());}return out;}
 static Map<String,Method> methods(ClassDef c){Map<String,Method> m=new TreeMap<>();for(Method x:c.getMethods())m.put(x.toString(),x);return m;}
 public static void main(String[] a)throws Exception{var l=load(a[0]);var r=load(a[1]);if(!l.keySet().equals(r.keySet()))throw new AssertionError("class inventory");int count=0,changed=0,total=0;Set<String> classes=new TreeSet<>();for(String n:l.keySet()){ClassDef x=l.get(n),y=r.get(n);if(x.getAccessFlags()!=y.getAccessFlags()||!Objects.equals(x.getSuperclass(),y.getSuperclass())||!x.getInterfaces().equals(y.getInterfaces())||!x.getAnnotations().equals(y.getAnnotations()))throw new AssertionError("class metadata "+n);Map<String,Method> lm=methods(x),rm=methods(y);if(!lm.keySet().equals(rm.keySet()))throw new AssertionError("method inventory "+n);for(String k:lm.keySet()){Method p=lm.get(k),q=rm.get(k);total++;if(p.getImplementation()==null){if(q.getImplementation()!=null)throw new AssertionError();continue;}if(q.getImplementation()==null||p.getImplementation().getRegisterCount()!=q.getImplementation().getRegisterCount())throw new AssertionError("register count "+k);if(!normal(p.getImplementation()).equals(normal(q.getImplementation())))throw new AssertionError("operation/branch/catch delta "+k);int hooks=0;for(Instruction i:q.getImplementation().getInstructions())if(hook(i))hooks++;if(hooks>0){count+=hooks;changed++;classes.add(n);}}}if(count!=33||changed!=30||classes.size()!=18)throw new AssertionError("hook scope "+count+" "+changed+" "+classes.size());System.out.println("PASS classes="+l.size()+" methods="+total+" original operation/register/reference/branch/catch semantics unchanged; only hooks="+count+" changed methods="+changed+" classes="+classes.size());}
}
